parameters.jsCode:
// Extrae los datos de la reunión desde el payload de Calendly (invitee.created).
const p = ($json.body && $json.body.payload) ? $json.body.payload : ($json.payload || $json);

// Teléfono: primero text_reminder_number, si no, lo busca en las preguntas del formulario.
let telRaw = p.text_reminder_number || '';
if (!telRaw && Array.isArray(p.questions_and_answers)) {
  for (const qa of p.questions_and_answers) {
    const d = String(qa.answer || '').replace(/\D/g, '');
    if (d.length >= 8) { telRaw = qa.answer; break; }
  }
}
const telefono = String(telRaw).replace(/\D/g, '');      // solo dígitos para guardar/cruzar
const to = telefono ? ('+' + telefono) : '';             // formato para enviar por WhatsApp

const ev = p.scheduled_event || {};
const fechaISO = ev.start_time || null;

function fmt(iso) {
  if (!iso) return '';
  try {
    return new Date(iso).toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', dateStyle: 'full', timeStyle: 'short' });
  } catch (e) { return iso; }
}
const fecha_hora_texto = fmt(fechaISO);

const mensaje = `¡Hola${p.name ? ' ' + p.name : ''}! Ahí vi que agendaste 🙌 Te confirmo la reunión para el ${fecha_hora_texto}. Si necesitás cambiar algo, avisame. ¡Gracias!`;

return [{ json: {
  nombre: p.name || null,
  telefono: telefono || null,
  email: p.email || null,
  fecha_hora: fechaISO,
  evento: ev.name || null,
  cancel_url: p.cancel_url || null,
  reschedule_url: p.reschedule_url || null,
  to,
  fecha_hora_texto,
  mensaje
} }];

